package main

import (
	"encoding/json"
	"net/http"
	"os"
	"sync"
	"time"
)

type RateLimitEntry struct {
	Count       int
	WindowStart time.Time
}

var (
	mu            sync.Mutex
	requestCounts = make(map[string]*RateLimitEntry)
)

const LIMIT = 5
const WINDOW = 10 * time.Second

func rateLimitMiddleware(next http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		mu.Lock()
		ip := r.RemoteAddr
		now := time.Now()
		entry, exists := requestCounts[ip]
		if !exists || now.Sub(entry.WindowStart) > WINDOW {
			requestCounts[ip] = &RateLimitEntry{Count: 1, WindowStart: now}
			mu.Unlock()
			next(w, r)
			return
		}
		entry.Count++
		if entry.Count > LIMIT {
			mu.Unlock()
			w.WriteHeader(http.StatusTooManyRequests)
			json.NewEncoder(w).Encode(map[string]string{"error": "Too many requests"})
			return
		}
		mu.Unlock()
		next(w, r)
	}
}

func main() {
	port := os.Getenv("PORT")
	if port == "" {
		port = "3000"
	}

	http.HandleFunc("/api", rateLimitMiddleware(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(map[string]interface{}{"message": "Success", "timestamp": time.Now().UnixMilli()})
	}))

	http.ListenAndServe(":"+port, nil)
}

