const express = require('express');
const app = express();
const port = process.env.PORT || 3000;

function rateLimiter({ windowMs = 10 * 1000, max = 5 } = {}) {
  const requestCounts = {};
  return (req, res, next) => {
    const ip = req.ip;
    const now = Date.now();
    if (!requestCounts[ip] || now - requestCounts[ip].windowStart > windowMs) {
      requestCounts[ip] = { count: 1, windowStart: now };
      res.setHeader('X-RateLimit-Remaining', max - 1);
      res.setHeader('X-RateLimit-Reset', Math.ceil((now + windowMs) / 1000));
      return next();
    }
    requestCounts[ip].count++;
    const remaining = Math.max(0, max - requestCounts[ip].count);
    res.setHeader('X-RateLimit-Remaining', remaining);
    res.setHeader('X-RateLimit-Reset', Math.ceil((requestCounts[ip].windowStart + windowMs) / 1000));
    if (requestCounts[ip].count > max) {
      return res.status(429).json({ error: 'Too many requests' });
    }
    next();
  };
}

